import numpy as np

def problem(x: np.ndarray) -> float:
    """
    A synthetic benchmark function with adjustable ELA characteristics.
    """
    if x.shape != (5,):
        raise ValueError("Input x must be a NumPy array of shape (5,).")

    # Scale and shift the input to the range [0, 1]
    x_scaled = (x + 5) / 10

    term1 = np.cos(10 * np.pi * x_scaled[0])
    term2 = (x_scaled[1]**2)

    def sinc(x):
        if np.abs(x) < 1e-8:
            return 1.0
        else:
            return np.sin(np.pi * x) / (np.pi * x)

    term3 = sinc(x_scaled[4]) * 0.1

    result = term1 + 0.5 * term2 + x_scaled[2] * x_scaled[3] * 0.01 + (x_scaled[4] % 0.1) * 0.1 + term3
    return float(result)
